/**
 * ==========================================================================
 * SCRIPT.JS - Mahalakshmi BS Portfolio (Multi-Page Edition)
 * Each section is its own page. This script handles:
 *   • Navbar scroll style
 *   • Mobile hamburger drawer
 *   • Scroll-reveal via IntersectionObserver
 *   • Project case-study modals (on projects.html)
 *   • Resume download (embeds real PDF via base64)
 * ==========================================================================
 */

(function () {
  'use strict';

  // ── Navbar scrolled style ──────────────────────────────────────────────────
  const navbar = document.getElementById('navbar');
  if (navbar) {
    function handleNavbarScroll() {
      navbar.classList.toggle('scrolled', window.scrollY > 40);
    }
    window.addEventListener('scroll', handleNavbarScroll, { passive: true });
    handleNavbarScroll();
  }

  // ── Mobile Hamburger Drawer ──────────────────────────────────────────────
  const hamburger = document.getElementById('hamburger');
  const navLinks  = document.getElementById('nav-links');

  if (hamburger && navLinks) {
    hamburger.addEventListener('click', function (e) {
      e.stopPropagation();
      const isOpen = navLinks.classList.toggle('open');
      hamburger.classList.toggle('open', isOpen);
      hamburger.setAttribute('aria-expanded', isOpen);
    });

    navLinks.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        navLinks.classList.remove('open');
        hamburger.classList.remove('open');
        hamburger.setAttribute('aria-expanded', false);
      });
    });

    document.addEventListener('click', function (e) {
      if (navbar && !navbar.contains(e.target)) {
        navLinks.classList.remove('open');
        hamburger.classList.remove('open');
        hamburger.setAttribute('aria-expanded', false);
      }
    });
  }

  // ── Scroll Reveal ──────────────────────────────────────────────────────────
  const reveals = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window && reveals.length) {
    const observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });

    reveals.forEach(function (el) { observer.observe(el); });
  } else {
    reveals.forEach(function (el) { el.classList.add('visible'); });
  }

  // ── Project Modals (projects.html only) ────────────────────────────────────
  const modalTriggers  = document.querySelectorAll('.project-modal-trigger');
  const modals         = document.querySelectorAll('.modal-overlay');
  const modalCloseBtns = document.querySelectorAll('.modal-close-btn');

  function openModal(id) {
    const m = document.getElementById('modal-' + id);
    if (m) {
      m.classList.add('active');
      document.body.classList.add('modal-open');
    }
  }

  function closeAllModals() {
    modals.forEach(function (m) { m.classList.remove('active'); });
    document.body.classList.remove('modal-open');
  }

  modalTriggers.forEach(function (trigger) {
    trigger.addEventListener('click', function (e) {
      e.preventDefault();
      openModal(this.getAttribute('data-project'));
    });
  });

  modalCloseBtns.forEach(function (btn) {
    btn.addEventListener('click', closeAllModals);
  });

  modals.forEach(function (modal) {
    modal.addEventListener('click', function (e) {
      if (e.target === this) closeAllModals();
    });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') closeAllModals();
  });

  // ── Resume Download ────────────────────────────────────────────────────────
  const downloadCvBtn = document.getElementById('download-cv');

  if (downloadCvBtn) {
    // Real resume PDF — base64 encoded
    const RESUME_B64 = '';

    downloadCvBtn.addEventListener('click', function (e) {
      e.preventDefault();

      // Toast notification
      let toastContainer = document.getElementById('toast-container');
      if (!toastContainer) {
        toastContainer = document.createElement('div');
        toastContainer.id = 'toast-container';
        Object.assign(toastContainer.style, {
          position: 'fixed', bottom: '32px', right: '32px',
          zIndex: '9999', display: 'flex', flexDirection: 'column', gap: '10px'
        });
        document.body.appendChild(toastContainer);
      }

      const toast = document.createElement('div');
      Object.assign(toast.style, {
        background: 'var(--ink)', color: '#ffffff',
        padding: '18px 24px', borderLeft: '4px solid var(--accent)',
        fontFamily: 'var(--sans)', fontSize: '0.88rem', fontWeight: '500',
        boxShadow: '0 8px 30px rgba(0,0,0,0.15)',
        transform: 'translateY(20px)', opacity: '0',
        transition: 'transform 0.3s cubic-bezier(0.16,1,0.3,1), opacity 0.3s ease'
      });
      toast.innerHTML = `
        <div style="display:flex;align-items:center;gap:12px;">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="color:var(--accent);flex-shrink:0;"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg>
          <div>
            <span style="display:block;font-weight:700;">Resume Download Initiated</span>
            <span style="color:var(--muted-soft);font-size:0.78rem;">Mahalakshmi_BS_Resume.pdf</span>
          </div>
        </div>`;
      toastContainer.appendChild(toast);
      setTimeout(function () {
        toast.style.transform = 'translateY(0)';
        toast.style.opacity   = '1';
      }, 50);

      // Trigger download
      const link = document.createElement('a');
      link.href     = 'data:application/pdf;base64,' + RESUME_B64;
      link.download = 'Mahalakshmi_BS_Resume.pdf';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      // Remove toast after 3.5 s
      setTimeout(function () {
        toast.style.transform = 'translateY(20px)';
        toast.style.opacity   = '0';
        setTimeout(function () { toastContainer.removeChild(toast); }, 300);
      }, 3500);
    });
  }

})();
